const s = wb.getWorksheet('Sheet2');
for (let r=2;r<=25;r++){
  const w = `$A$2:$A$25,A${r},$C$2:$C$25,">="&EDATE(C${r},-3),$C$2:$C$25,"<="&C${r}`;
  s.getRange('E'+r).setValue(`=IF(COUNTIFS(${w})<4,"n/a",AVERAGEIFS($D$2:$D$25,${w}))`);
}
const out=[]; for (let r=2;r<=25;r++){ const x=s.getRange('E'+r); out.push(`E${r} A=${s.getRange('A'+r).getValue()} D=${s.getRange('D'+r).getValue()} v=${JSON.stringify(x.getValue())} t=${x.getText()} F=${s.getRange('F'+r).getText()} fmt=${x.getStyle().getNumberFormat()}`);} 
log(out.join('\n')); log(s.getRange('E25').getFormula());
log(wb.evaluate('=AVERAGE(D9:D12)'), wb.evaluate('=AVERAGE(D22:D25)'), wb.evaluate('=AVERAGE(D18:D21)'));

